package org.mockito.internal.stubbing.answers;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import org.mockito.invocation.InvocationOnMock;
import org.mockito.stubbing.Answer;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertSame;

/**
 * Unit tests for CallsRealMethods#answer.
 */
public class CallsRealMethods_answer_TriageGen1Test {

    @Test
    public void testAnswerReturnsValueFromRealMethod() throws Throwable {
        // Arrange
        CallsRealMethods answerer = new CallsRealMethods();
        String expectedValue = "Hello World";

        InvocationOnMock invocation = new InvocationOnMock() {
            @Override
            public Object callRealMethod() throws Throwable {
                return expectedValue;
            }

            @Override
            public Class<?> getMock() {
                return null;
            }

            @Override
            public Object[] getArguments() {
                return new Object[0];
            }

            @Override
            public Object getMockedBehavior() {
                return null;
            }
        };

        // Act
        Object result = answerer.answer(invocation);

        // Assert
        assertEquals(expectedValue, result);
    }

    @Test
    public void testAnswerReturnsNullFromRealMethod() throws Throwable {
        // Arrange
        CallsRealMethods answerer = new CallsRealMethods();

        InvocationOnMock invocation = new InvocationOnMock() {
            @Override
            public Object callRealMethod() throws Throwable {
                return null;
            }

            @Override
            public Class<?> getMock() {
                return null;
            }

            @Override
            public Object[] getArguments() {
                return new Object[0];
            }

            @Override
            public Object getMockedBehavior() {
                return null;
            }
        };

        // Act
        Object result = answerer.answer(invocation);

        // Assert
        assertNull(result);
    }

    @Test(expected = RuntimeException.class)
    public void testAnswerThrowsExceptionFromRealMethod() throws Throwable {
        // Arrange
        CallsRealMethods answerer = new CallsRealMethods();

        InvocationOnMock invocation = new InvocationOnMock() {
            @Override
            public Object callRealMethod() throws Throwable {
                throw new RuntimeException("Real method exception");
            }

            @Override
            public Class<?> getMock() {
                return null;
            }

            @Override
            public Object[] getArguments() {
                return new Object[0];
            }

            @Override
            public Object getMockedBehavior() {
                return null;
            }
        };

        // Act
        answerer.answer(invocation);

        // Assert is handled by expected exception
    }

    @Test
    public void testAnswerReturnsObjectInstance() throws Throwable {
        // Arrange
        CallsRealMethods answerer = new CallsRealMethods();
        Object expectedInstance = new Object();

        InvocationOnMock invocation = new InvocationOnMock() {
            @Override
            public Object callRealMethod() throws Throwable {
                return expectedInstance;
            }

            @Override
            public Class<?> getMock() {
                return null;
            }

            @Override
            public Object[] getArguments() {
                return new Object[0];
            }

            @Override
            public Object getMockedBehavior() {
                return null;
            }
        };

        // Act
        Object result = answerer.answer(invocation);

        // Assert
        assertSame(expectedInstance, result);
    }
}
